current_date_text = str(current_date_and_time['date']).strip()
month_numbers = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6, 'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}
def normalized_date_token(token):
    value = token.strip().strip('.').lower()
    if len(value) > 2 and value[-2:] in ('st', 'nd', 'rd', 'th') and value[:-2].isdigit():
        value = value[:-2]
    return value
if len(current_date_text) >= 10 and current_date_text[4] == '-' and current_date_text[7] == '-':
    date_tokens = current_date_text[:10].replace('-', ' ').split()
else:
    date_tokens = [normalized_date_token(token) for token in current_date_text.replace(',', ' ').replace('/', ' ').replace('-', ' ').split()]
month_position = None
for token_index, token in enumerate(date_tokens):
    if token[:3] in month_numbers and token[:3].isalpha():
        month_position = token_index
        break
if month_position is not None:
    month = month_numbers[date_tokens[month_position][:3]]
    year_candidates = [(index, int(token)) for index, token in enumerate(date_tokens) if token.isdigit() and len(token) == 4]
    if not year_candidates:
        raise RuntimeError('The phone date did not contain a four-digit year')
    year_index, year = year_candidates[-1]
    after_month_days = [int(token) for index, token in enumerate(date_tokens) if index > month_position and index != year_index and token.isdigit()]
    before_month_days = [int(token) for index, token in enumerate(date_tokens) if index < month_position and index != year_index and token.isdigit()]
    day_candidates = after_month_days if after_month_days else before_month_days
    if not day_candidates:
        raise RuntimeError('The phone date did not contain a day of month')
    day = day_candidates[0]
else:
    numeric_tokens = [token for token in date_tokens if token.isdigit()]
    if len(numeric_tokens) < 3:
        raise RuntimeError('The phone date could not be parsed')
    if len(numeric_tokens[0]) == 4:
        year, month, day = [int(value) for value in numeric_tokens[:3]]
    elif len(numeric_tokens[-1]) == 4:
        first_value, second_value, year = [int(value) for value in (numeric_tokens[0], numeric_tokens[1], numeric_tokens[-1])]
        if first_value > 12:
            day, month = first_value, second_value
        else:
            month, day = first_value, second_value
    else:
        raise RuntimeError('The phone date did not contain a four-digit year')
def days_in_month_for(target_year, target_month):
    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    leap_year = target_year % 4 == 0 and (target_year % 100 != 0 or target_year % 400 == 0)
    if leap_year:
        month_lengths[1] = 29
    return month_lengths[target_month - 1]
if month < 1 or month > 12 or day < 1 or day > days_in_month_for(year, month):
    raise RuntimeError('The parsed phone date is not a valid calendar date')
window_end = f'{year:04d}-{month:02d}-{day:02d}'
