like_results = {}
comment_results = {}
for transaction_id in target_transaction_ids:
    if transaction_id in pending_like_ids:
        like_results[transaction_id] = apis.venmo.like_transaction(transaction_id=transaction_id, access_token=venmo_access_token)
    comment_results[transaction_id] = apis.venmo.create_transaction_comment(transaction_id=transaction_id, comment='Thank you!', access_token=venmo_access_token)

post_transactions_by_coworker = {}
for coworker_email in coworker_emails:
    post_pages = []
    post_page_index = 0
    while True:
        post_page = apis.venmo.show_transactions(access_token=venmo_access_token, user_email=coworker_email, min_created_at=window_start, max_created_at=window_end, direction='received', page_index=post_page_index, page_limit=20)
        post_pages.append(post_page)
        if len(post_page) < 20:
            break
        post_page_index += 1
    post_transactions_by_coworker[coworker_email] = [transaction for page in post_pages for transaction in page]
post_transactions_by_id = {}
for transactions in post_transactions_by_coworker.values():
    for transaction in transactions:
        post_transactions_by_id[transaction['transaction_id']] = transaction
verification_records = []
for transaction_id in target_transaction_ids:
    post_transaction = post_transactions_by_id.get(transaction_id)
    liked_now = post_transaction is not None and bool(post_transaction.get('liked'))
    comment_count_now = int(post_transaction.get('comment_count', -1)) if post_transaction is not None else -1
    comment_id_created = transaction_id in comment_results and comment_results[transaction_id].get('comment_id') is not None
    comment_count_advanced = comment_count_now >= pre_mutation_state[transaction_id]['comment_count'] + 1
    target_verified = liked_now and comment_id_created and comment_count_advanced
    verification_records.append({'transaction_id': transaction_id, 'liked_now': liked_now, 'comment_id_created': comment_id_created, 'comment_count_before': pre_mutation_state[transaction_id]['comment_count'], 'comment_count_now': comment_count_now, 'verified': target_verified})
verification_passed = all(record['verified'] for record in verification_records)
print({'target_count': len(target_transaction_ids), 'verified_target_count': sum(1 for record in verification_records if record['verified']), 'verification_passed': verification_passed, 'checks': verification_records})
if not verification_passed:
    raise RuntimeError('One or more target transactions failed post-mutation verification')
